diff --git a/src/hb-raster-draw.cc b/src/hb-raster-draw.cc
index c39583d..46ebf73 100644
--- a/src/hb-raster-draw.cc
+++ b/src/hb-raster-draw.cc
@@ -1390,8 +1390,10 @@ edge_sweep_row (int32_t                *area,
       fy_prev = fy_b;
     }

-    if (likely (cx1 <= col_max))
-      cell_add (area, cover, width, cx1 - x_org, 0, fy_prev, fx1, fy1, wind, x_min, x_max);
+    /* Final boundary cell.  cell_add() clamps any column outside
+       [0, width) to the surface, so no separate in-window guard is
+       needed here. */
+    cell_add (area, cover, width, cx1 - x_org, 0, fy_prev, fx1, fy1, wind, x_min, x_max);
   }
   else
   {

diff --git a/src/hb-raster-draw.cc b/src/hb-raster-draw.cc
index 5134f7f..09742f8 100644
--- a/src/hb-raster-draw.cc
+++ b/src/hb-raster-draw.cc
@@ -1257,19 +1257,18 @@ cell_add (Area *area, Cover *cover, unsigned width, int col,
 	  int32_t fx0, int32_t fy0, int32_t fx1, int32_t fy1, int32_t wind,
 	  unsigned &x_min, unsigned &x_max)
 {
-  if (unlikely ((unsigned) col >= width))
+  if (unlikely (col < 0))
   {
-    if (unlikely (col < 0))
-    {
-      /* Edge is to the left of the surface.  The winding contribution
-       * still carries into the visible region, so add the cover delta
-       * to column 0.  Area is not added since the edge doesn't cross
-       * column 0's cell. */
-      int32_t dy = fy1 - fy0;
-      cover[0] += (Cover) (dy * wind);
-      x_min = hb_min (x_min, 0u);
-      x_max = hb_max (x_max, 0u);
-    }
+    /* Edge is to the left of the surface.  The winding contribution
+     * still carries into the visible region, so add the cover delta
+     * to column 0.  Area is not added since the edge doesn't cross
+     * column 0's cell.  Columns to the right of the surface do not
+     * reach cell_add(): edge_sweep_row() clips the per-column walk to
+     * the visible window before calling in (see #6251). */
+    int32_t dy = fy1 - fy0;
+    cover[0] += (Cover) (dy * wind);
+    x_min = hb_min (x_min, 0u);
+    x_max = hb_max (x_max, 0u);
     return;
   }
   int32_t dy = fy1 - fy0;
